#### 5.21.2 案例二：逐行计算工龄工资（需要行间状态）

**需求**：给每名员工发工龄工资 —— 入职满 1 年发 100 元，满 3 年发 300 元，满 5 年发 500 元，满 10 年发 1000 元；工龄工资累加到基本工资中。

```sql
DROP PROCEDURE IF EXISTS pro_seniority_pay;

DELIMITER $$

CREATE PROCEDURE pro_seniority_pay(OUT p_msg VARCHAR(500))
BEGIN
    DECLARE v_done     INT           DEFAULT 0;
    DECLARE v_empID    INT           DEFAULT 0;
    DECLARE v_name     VARCHAR(50)   DEFAULT '';
    DECLARE v_hireDate DATE          DEFAULT NULL;
    DECLARE v_years    INT           DEFAULT 0;
    DECLARE v_bonus    DECIMAL(10,2) DEFAULT 0;
    DECLARE v_msg      VARCHAR(500)  DEFAULT '';

    DECLARE cur_emp CURSOR FOR
        SELECT EmpID, EmpName, HireDate FROM Employee ORDER BY EmpID;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

    OPEN cur_emp;

    pay_loop: LOOP
        FETCH cur_emp INTO v_empID, v_name, v_hireDate;
        IF v_done = 1 THEN
            LEAVE pay_loop;
        END IF;

        -- 用 DATEDIFF 计算工龄年数（此处简化：按 365 天为一年）
        SET v_years = FLOOR(DATEDIFF(CURDATE(), v_hireDate) / 365);

        -- 用 CASE 分档确定工龄工资
        CASE
            WHEN v_years >= 10 THEN SET v_bonus = 1000.00;
            WHEN v_years >= 5  THEN SET v_bonus = 500.00;
            WHEN v_years >= 3  THEN SET v_bonus = 300.00;
            WHEN v_years >= 1  THEN SET v_bonus = 100.00;
            ELSE SET v_bonus = 0.00;
        END CASE;

        -- 累加到工资
        UPDATE Employee SET Salary = Salary + v_bonus WHERE EmpID = v_empID;

        SET v_msg = CONCAT(v_msg, v_name, '(',
                           v_years, '年)：+', v_bonus, '元；');
    END LOOP pay_loop;

    CLOSE cur_emp;

    SET p_msg = v_msg;
END $$

DELIMITER ;

CALL pro_seniority_pay(@msg);
SELECT @msg AS '工龄工资发放明细';
SELECT EmpID, EmpName, HireDate, Salary FROM Employee ORDER BY EmpID;
```

