```sql
-- 先建一张汇报表
CREATE TABLE IF NOT EXISTS DeptReport (
    RptID     INT          NOT NULL AUTO_INCREMENT,
    RptText   VARCHAR(200) DEFAULT NULL,
    RptTime   DATETIME     DEFAULT NULL,
    CONSTRAINT pk_deptreport PRIMARY KEY (RptID)
