CREATE PROCEDURE pro_dept_report(OUT p_cnt INT)
BEGIN
    DECLARE v_done     INT          DEFAULT 0;
    DECLARE v_deptName VARCHAR(50)  DEFAULT '';
    DECLARE v_deptAddr VARCHAR(100) DEFAULT '';
    DECLARE v_text     VARCHAR(200) DEFAULT '';
    DECLARE v_cnt      INT          DEFAULT 0;

    DECLARE cur_dept CURSOR FOR
        SELECT DeptName, DeptAddr FROM Department ORDER BY DeptID;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

    OPEN cur_dept;

    rpt_loop: LOOP
        FETCH cur_dept INTO v_deptName, v_deptAddr;
        IF v_done = 1 THEN
            LEAVE rpt_loop;
